/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
[ExtensionOf(classStr(InventTransferUpdPick))]
final class METInventTransferUpdPick_Extension
{
}

Method.Source:
    /// <summary>
    ///    Handles initialization and updates, for example, of journals and ledger transactions, that are
    ///    performed during the update.
    /// </summary>
    public void run()
    {
        next run();

        InventTransferLine::METAdjustShipRemain(wmsPickingRoute.pickingRouteId);

        //Update transfer line extraction status
        InventTransferLine::metUpdateExtractionStatus(wmsPickingRoute.pickingRouteId);

        //Update transfer header extraction status
        METInventTransferTableExt::UpdateExtractionStatus(inventTransferTable.TransferId);
    }

    /// <summary>
    /// CB715_TransferOrderExtract
    /// New version of newParmBuffer method that creates InventTransferParmLine after inserting header
    /// and updated query to select only TO lines where extraction status=”Ready for extract” only.
    /// </summary>
    /// <param name = "_inventTransferParmTable">Transfer order picking list update table</param>
    /// <returns>An instance of the <c>InventTransferUpdPick</c> class.</returns>
    public static InventTransferUpdPick METNewParmBuffer(InventTransferParmTable _inventTransferParmTable)
    {
        _inventTransferParmTable.skipTTSCheck(true);
        _inventTransferParmTable.ParmBuffer::initParmId();
        // do no create lines here
        //_inventTransferParmTable.write();
        _inventTransferParmTable.insert(false);

        // Lines created with the new query to filter TO lines where extraction status=”Ready for extract” only.
        InventTransferParmLine::METCreatePickLines(_inventTransferParmTable);

        InventTransferUpdPick inventTransferUpdPick = InventTransferUpdPick::construct();
        inventTransferUpdPick.parmParmBuffer(_inventTransferParmTable);

        return inventTransferUpdPick;
    }
